def getMaxRepetitions(s1, n1, s2, n2):
    if not n1: return 0
    count1, count2, i, j = 0, 0, 0, 0
    index_map = {}
    while True:
        if i not in index_map:
            index_map[i] = (count1, count2)
        else:
            break
        count1 += 1
        for _ in range(len(s1)):
            if s1[i % len(s1)] == s2[j % len(s2)]:
                j += 1
            i += 1
        count2 = j // len(s2)
    if count1 < n1:
        start_count1, start_count2 = index_map[i]
        loop_count1 = count1 - start_count1
        loop_count2 = count2 - start_count2
        full_loops = (n1 - start_count1) // loop_count1
        remaining_count1 = start_count1 + full_loops * loop_count1
        remaining_count2 = start_count2 + full_loops * loop_count2
        i = i % len(s1)
        while remaining_count1 < n1:
            remaining_count1 += 1
            for _ in range(len(s1)):
                if s1[i % len(s1)] == s2[j % len,s2)]:
                    j += 1
                i += 1
            remaining_count2 = j // len(s2)
        count2 = remaining_count2
    return count2 // n2
